  },
  "goal": {
    "statement": "Every product lookup by cashier returns correct store-scoped results in < 200ms, and price changes never retroactively modify existing order items.",
    "metric": "Cashier product search latency p95 < 200ms. Zero cross-store product leaks. Zero order items with retroactively changed price.",
    "deadline": "2026-05-10"
  },
  "actors": [
    {
      "id": "A-PROD-01",
      "name": "Store Manager / Quản lý cửa hàng",
      "goal": "Maintain an accurate and current product catalog",
      "impacts": [
        {
          "action": "Create product with correct VNĐ price + VAT rate",
          "deliverable": "POST /api/v1/products",
          "hinders_if_not_done": "Cashiers cannot find products to sell"
        },
        {
          "action": "Update price when cost changes",
          "deliverable": "PATCH /api/v1/products/:id",
          "hinders_if_not_done": "Sales at wrong price without audit trail"
        },
        {
          "action": "Deactivate discontinued products",
          "deliverable": "PATCH /api/v1/products/:id/deactivate",
          "hinders_if_not_done": "Cashiers try to sell products no longer available"
        }
      ]
    },
    {
      "id": "A-PROD-02",
      "name": "Admin",
      "goal": "Oversee product catalog across all stores",
      "impacts": [
        {
          "action": "View and manage all stores' products",
          "deliverable": "Admin role bypass on product endpoints",
          "hinders_if_not_done": "Admin cannot audit product inconsistencies across stores"
        }
      ]
    },
    {
      "id": "A-PROD-03",
      "name": "Cashier / Thu ngân",
      "goal": "Find products quickly when processing a sale",
      "impacts": [
        {
          "action": "Search product by name or SKU (Vietnamese diacritic-insensitive)",
          "deliverable": "GET /api/v1/products?q=...",
          "hinders_if_not_done": "Cashier cannot find 'Bánh Mì' by typing 'banh mi' — slows down POS"
        },
        {
          "action": "Get product details by ID before adding to order",
          "deliverable": "GET /api/v1/products/:id",
          "hinders_if_not_done": "Cashier cannot confirm price before checkout"
        }
      ]
    },
    {
      "id": "A-PROD-04",
      "name": "Order System (downstream consumer)",
      "goal": "Snapshot product price and VAT at order-item creation time",
      "impacts": [
        {
          "action": "Read product.priceVnd + product.taxRatePercent at item-add time",
          "deliverable": "OrderItem stores unitPriceVnd + taxRatePercent snapshot",
          "hinders_if_not_done": "Historical orders reflect future price changes — accounting error"
        }
      ]
    }
  ],
  "constraints": [
    "storeId on every product query MUST come from JWT — never from URL or body",
    "unaccent PostgreSQL extension must be enabled before product search is usable",
    "Soft-delete only — no Product rows may be hard-deleted"
  ]
