{
  "meta": {
    "version": 1,
    "last_updated": "2025-01-01",
    "title": "Developer Onboarding Guide",
    "owner": "vibe-devops-general"
  },
  "quick_facts": {
    "estimated_time": "2-4 hours",
    "prerequisites": [
      "Docker Desktop installed",
      "Node.js 20.x installed",
      "Git configured with SSH key"
    ],
    "contact": "team lead"
  },
  "content": {
    "tldr": "Clone → configure .env → docker compose up → run migrations → verify ports 3000/5173/3001.",
    "steps": [
      {
        "step": 1,
        "title": "Clone the repository",
        "command": "git clone <repo-url> && cd EAM",
        "notes": "Use SSH clone. HTTPS may fail behind corporate proxy."
      },
      {
        "step": 2,
        "title": "Configure environment files",
        "command": "cp backend/.env.example backend/.env && cp frontend/.env.example frontend/.env.local",
        "notes": "Fill in all values marked <vault>. Get values from team lead."
      },
      {
        "step": 3,
        "title": "Start Docker services",
        "command": "docker compose up -d postgres redis",
        "notes": "Wait for postgres health check to pass before next step."
      },
      {
        "step": 4,
        "title": "Install dependencies",
        "command": "cd backend && npm ci && cd ../frontend && npm ci",
        "notes": "Use npm ci (not npm install) to respect lockfile."
      },
      {
        "step": 5,
        "title": "Run database migrations",
        "command": "cd backend && npm run migration:run",
        "notes": "Should complete with 'No pending migrations'."
      },
      {
        "step": 6,
        "title": "Start all services",
        "command": "docker compose up",
        "notes": "Backend: http://localhost:3000 | Frontend: http://localhost:5173 | Wiki: http://localhost:3001"
      },
      {
        "step": 7,
        "title": "Verify setup",
        "command": "curl http://localhost:3000/health",
        "notes": "Should return {\"status\":\"ok\"}. If not, check docker logs."
      }
    ],
    "common_issues": [
      {
        "issue": "Port 5432 already in use",
        "fix": "Stop local PostgreSQL: sudo service postgresql stop"
      },
      {
        "issue": "Migration fails: relation does not exist",
        "fix": "Run: docker compose exec postgres psql -U $DATABASE_USER -c 'CREATE EXTENSION IF NOT EXISTS \"uuid-ossp\"'"
      },
      {
        "issue": "Frontend shows 'VITE_API_URL not set'",
        "fix": "Ensure frontend/.env.local has VITE_API_URL=http://localhost:3000"
      }
    ]
  },
  "audit": [
    {
      "version": 1,
      "timestamp": "2025-01-01T00:00:00Z",
      "author": "vibe-devops-general",
      "action": "created",
      "note": "Initial onboarding guide"
    }
  ]
}

